enum Prioritas { Rendah, Sedang, Tinggi }
type Status = "baru" | "proses" | "selesai";
const KATEGORI = { Kerja: "kerja", Rumah: "rumah" } as const;
type Kategori = (typeof KATEGORI)[keyof typeof KATEGORI];

type Tugas = { judul: string; prioritas: Prioritas; status: Status; kategori: Kategori };
const t: Tugas = { judul: "Laporan", prioritas: Prioritas.Tinggi, status: "proses", kategori: KATEGORI.Kerja };
console.log(t.prioritas, t.status, t.kategori);
console.log(Prioritas[t.prioritas]);
console.log(Object.values(KATEGORI).join(","));

