const UKURAN = { Kecil: "S", Sedang: "M", Besar: "L" } as const;
type Ukuran = (typeof UKURAN)[keyof typeof UKURAN];
const HARGA: Record<Ukuran, number> = { S: 15000, M: 18000, L: 22000 };
function harga(u: Ukuran): number {
  return HARGA[u];
}
console.log(harga(UKURAN.Besar));
